/* make.fun frontend — a clean, fast board of open bounties */
* { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #ffffff;
  --fg: #0f172a;
  --muted: #64748b;
  --line: #e2e8f0;
  --accent: #0b5cad;
  --accent-hover: #084a82;
  --ok: #059669;
  --warn: #d97706;
  --bad: #dc2626;
  --chip: #f1f5f9;
  --radius: 8px;
}

html { scroll-behavior: smooth; }
body {
  margin: 0 auto;
  max-width: 1000px;
  padding: 0 16px 64px;
  font: 16px/1.55 -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
  color: var(--fg);
  background: var(--bg);
}
header { padding: 24px 0 8px; border-bottom: 1px solid var(--line); }
header h1 {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.5px;
}
header .sub { color: var(--muted); font-size: 14px; margin-top: 4px; }

nav { margin: 16px 0 24px; display: flex; gap: 8px; flex-wrap: wrap; }
nav a, nav button {
  text-decoration: none;
  color: var(--muted);
  font-size: 13px;
  padding: 6px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: transparent;
  cursor: pointer;
  font-family: inherit;
}
nav a.active, nav button.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}
nav a:hover { border-color: var(--accent); color: var(--accent); }

.search { margin: 12px 0 20px; position: relative; max-width: 420px; }
.search input {
  width: 100%;
  padding: 10px 14px 10px 40px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  font: inherit;
  outline: none;
}
.search input:focus { border-color: var(--accent); }
.search::before {
  content: '🔍';
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 16px;
}

h2 { font-size: 20px; margin: 32px 0 12px; }

/* Board */
.board { list-style: none; padding: 0; display: grid; gap: 14px; }
.board li {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  display: grid;
  grid-template-columns: 1fr 110px 100px 100px;
  gap: 12px;
  align-items: start;
  transition: transform 0.1s, box-shadow 0.1s;
}
.board li:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.06); }
.board h3 { font-size: 15px; font-weight: 600; margin-bottom: 4px; line-height: 1.3; }
.board h3 a { text-decoration: none; color: var(--fg); }
.board h3 a:hover { color: var(--accent); }
.board p { font-size: 13px; color: var(--muted); margin-bottom: 8px; }
.board .meta { display: flex; gap: 10px; font-size: 12px; color: var(--muted); }
.board .meta span { white-space: nowrap; }
.board .reward { font-weight: 700; font-size: 15px; color: var(--accent); }
.board .entries { color: var(--muted); font-size: 12px; }

.deadline { font-weight: 600; }
.deadline.urgent { color: var(--bad); }
.deadline.soon { color: var(--warn); }
.deadline.ok { color: var(--ok); }

.skills { margin-top: 8px; display: flex; gap: 6px; flex-wrap: wrap; }
.skill {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 12px;
  background: var(--chip);
  color: var(--muted);
}

/* Bounty page */
.page { max-width: 760px; }
.page nav a { margin-right: 16px; }
.page h1 { font-size: 26px; margin-bottom: 6px; }
.page .summary { font-size: 16px; color: var(--muted); margin-bottom: 20px; line-height: 1.6; }
.page .hero { display: flex; gap: 16px; margin-bottom: 24px; gap-align: start; }
.page .hero .big { font-size: 30px; font-weight: 800; color: var(--accent); white-space: nowrap; }
.page .hero .meta { display: flex; flex-direction: column; gap: 4px; font-size: 13px; color: var(--muted); }
.page .hero .deadline { font-weight: 600; color: var(--fg); }
.page .dl { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 24px; }
.page dl { display: grid; grid-template-columns: 130px 1fr; gap: 6px 16px; margin-bottom: 16px; }
.page dt { font-weight: 600; color: var(--muted); font-size: 13px; }
.page dd { font-size: 14px; margin-bottom: 2px; }
.page .description { white-space: pre-wrap; line-height: 1.7; margin-bottom: 24px; }
.page .description h3 { font-size: 15px; margin: 16px 0 6px; color: var(--fg); }
.page .description ul { margin: 6px 0 12px 20px; }
.page .description li { margin-bottom: 4px; color: var(--fg); }

footer { margin-top: 48px; padding-top: 24px; border-top: 1px solid var(--line); color: var(--muted); font-size: 13px; text-align: center; }

.loading { padding: 40px; text-align: center; color: var(--muted); }
.error { padding: 40px; text-align: center; color: var(--bad); }
.error button { margin-top: 12px; padding: 8px 16px; border: 1px solid var(--line); background: transparent; border-radius: var(--radius); cursor: pointer; font: inherit; }
.error button:hover { background: var(--chip); }

@media (max-width: 700px) {
  .board li { grid-template-columns: 1fr; }
  .board .meta { flex-wrap: wrap; }
  .page .dl { grid-template-columns: 1fr; }
  .page .hero { flex-direction: column; }
  .page .hero .big { font-size: 22px; white-space: normal; }
}
